package settings

import (
	"context"
	"encoding/json"
	"errors"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/hkjang/bbmcp/internal/crypto"
)

// Store reads and writes settings groups with a process-local cache.
type Store struct {
	pool   *pgxpool.Pool
	sealer *crypto.Sealer

	mu    sync.RWMutex
	cache map[string]cached
}

// cached is one group as read from the database.
type cached struct {
	body json.RawMessage
	at   time.Time
}

// cacheTTL bounds how long a process serves a group without re-reading it.
// Put refreshes only the process that saved; with more than one gateway on
// the same database, the others pick the change up within this window.
const cacheTTL = 30 * time.Second

// NewStore builds a settings store.
func NewStore(pool *pgxpool.Pool, sealer *crypto.Sealer) *Store {
	return &Store{pool: pool, sealer: sealer, cache: map[string]cached{}}
}

// Sealer exposes the shared sealer for callers that need to encrypt a field.
func (s *Store) Sealer() *crypto.Sealer { return s.sealer }

// raw loads a group's JSON, consulting the cache first.
func (s *Store) raw(ctx context.Context, key string) (json.RawMessage, error) {
	s.mu.RLock()
	v, cachedOK := s.cache[key]
	s.mu.RUnlock()
	if cachedOK && time.Since(v.at) < cacheTTL {
		return v.body, nil
	}

	var body []byte
	err := s.pool.QueryRow(ctx, `SELECT value_json FROM settings WHERE key=$1`, key).Scan(&body)
	if errors.Is(err, pgx.ErrNoRows) {
		body = nil
	} else if err != nil {
		// A failed refresh keeps the last known settings. Falling back to the
		// defaults instead would, for one, drop an IP allowlist while the
		// database is briefly unavailable.
		if cachedOK {
			return v.body, nil
		}
		return nil, err
	}
	s.mu.Lock()
	s.cache[key] = cached{body: body, at: time.Now()}
	s.mu.Unlock()
	return body, nil
}

// load unmarshals a group over the provided defaults.
func load[T any](ctx context.Context, s *Store, key string, def T) (T, error) {
	body, err := s.raw(ctx, key)
	if err != nil {
		return def, err
	}
	if len(body) == 0 {
		return def, nil
	}
	out := def
	if err := json.Unmarshal(body, &out); err != nil {
		return def, err
	}
	return out, nil
}

// Put replaces a group and invalidates the cache.
func (s *Store) Put(ctx context.Context, key string, value any, actor string) error {
	body, err := json.Marshal(value)
	if err != nil {
		return err
	}
	_, err = s.pool.Exec(ctx, `
		INSERT INTO settings(key, value_json, updated_at, updated_by)
		VALUES ($1, $2, NOW(), $3)
		ON CONFLICT (key) DO UPDATE
		   SET value_json = EXCLUDED.value_json,
		       updated_at = NOW(),
		       updated_by = EXCLUDED.updated_by`, key, body, actor)
	if err != nil {
		return err
	}
	s.mu.Lock()
	s.cache[key] = cached{body: body, at: time.Now()}
// Package config loads the small set of environment variables bbmcp accepts.
//
// Everything else (Keycloak, Bitbucket, AI, policy) is configured at runtime
// through the admin UI and stored encrypted in PostgreSQL, so that an
// air-gapped deployment only needs these four values.
package config

import (
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"strings"
)

// Config holds the process-level configuration.
type Config struct {
	DatabaseURL          string
	BootstrapAdmin       string
	BootstrapAdminPasswd string
	EncryptionKey        []byte
	Addr                 string
}

// Load reads and validates configuration from the environment.
func Load() (*Config, error) {
	c := &Config{
		DatabaseURL:          firstEnv("DATABASE_URL", "POSTGRES_DSN"),
		BootstrapAdmin:       firstEnv("BOOTSTRAP_ADMIN"),
		BootstrapAdminPasswd: firstEnv("BOOTSTRAP_ADMIN_PASSWORD"),
		Addr:                 envOr("BBMCP_ADDR", ":8080"),
	}

	var missing []string
	if c.DatabaseURL == "" {
		missing = append(missing, "DATABASE_URL")
	}
	if c.BootstrapAdmin == "" {
		missing = append(missing, "BOOTSTRAP_ADMIN")
	}
	if c.BootstrapAdminPasswd == "" {
		missing = append(missing, "BOOTSTRAP_ADMIN_PASSWORD")
	}
	raw := firstEnv("ENCRYPTION_KEY")
	if raw == "" {
		missing = append(missing, "ENCRYPTION_KEY")
	}
	if len(missing) > 0 {
		return nil, fmt.Errorf("필수 환경변수 누락: %s", strings.Join(missing, ", "))
	}

	key, err := parseKey(raw)
	if err != nil {
		return nil, fmt.Errorf("ENCRYPTION_KEY: %w", err)
	}
	c.EncryptionKey = key
	return c, nil
}

// parseKey accepts a 32-byte key as hex, base64, or raw text.
func parseKey(raw string) ([]byte, error) {
	raw = strings.TrimSpace(raw)
	if b, err := hex.DecodeString(raw); err == nil && len(b) == 32 {
		return b, nil
	}
	if b, err := base64.StdEncoding.DecodeString(raw); err == nil && len(b) == 32 {
		return b, nil
	}
	if b, err := base64.RawURLEncoding.DecodeString(raw); err == nil && len(b) == 32 {
		return b, nil
	}
	if len(raw) == 32 {
		return []byte(raw), nil
	}
	return nil, errors.New("32바이트 키가 필요합니다 (hex 64자, base64 44자, 또는 평문 32자)")
}

func firstEnv(keys ...string) string {
	for _, k := range keys {
		if v := strings.TrimSpace(os.Getenv(k)); v != "" {
			return v
		}
	}
	return ""
}

func envOr(key, def string) string {
	if v := strings.TrimSpace(os.Getenv(key)); v != "" {
		return v
	}
	return def
}
// Package mcp implements the Model Context Protocol endpoint of bbmcp over
// Streamable HTTP, including the OAuth protected-resource metadata that lets
// an MCP client discover Keycloak on its own.
package mcp

import "encoding/json"

// ProtocolVersion is the MCP revision bbmcp speaks.
const ProtocolVersion = "2025-06-18"

// Request is a JSON-RPC 2.0 request or notification.
type Request struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Method  string          `json:"method"`
	Params  json.RawMessage `json:"params,omitempty"`
}

// IsNotification reports whether the message expects no response.
func (r *Request) IsNotification() bool { return len(r.ID) == 0 }

// Response is a JSON-RPC 2.0 response.
type Response struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Result  any             `json:"result,omitempty"`
	Error   *RPCError       `json:"error,omitempty"`
}

// RPCError is a JSON-RPC error object.
type RPCError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
	Data    any    `json:"data,omitempty"`
}

// Standard JSON-RPC error codes plus the MCP-specific ones bbmcp uses.
const (
	CodeParseError     = -32700
	CodeInvalidRequest = -32600
	CodeMethodNotFound = -32601
	CodeInvalidParams  = -32602
	CodeInternalError  = -32603
)

func ok(id json.RawMessage, result any) *Response {
	return &Response{JSONRPC: "2.0", ID: id, Result: result}
}

func fail(id json.RawMessage, code int, message string, data any) *Response {
	return &Response{JSONRPC: "2.0", ID: id, Error: &RPCError{Code: code, Message: message, Data: data}}
}

// ToolDescriptor is one entry of a tools/list response.
type ToolDescriptor struct {
	Name        string         `json:"name"`
